/*Sentinel						--Index 411*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('FK', 'Default', 'Sentinel', 'Models that are adjacent to a Sentinel structure add +1ST to all defense rolls.');
/*Vulnerable: Magic				--Index 412*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('1.0', 'Default', 'Vulnerable: Magic', '');
/*Retreat						--Index 413*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('FK', 'Default', 'Retreat', 'After completing an action with Retreat, using the rules for Push, the model''s player moves the model with Retreat five squares away from its target or the square which the target occupied.');
/*Charge						--Index 414*/	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('FK', 'Default', 'Charge', 'When a model with Charge uses a Lance area effect, after resolving all other effects of the Lance, the model may be placed in any unoccupied square that was affected by the Lance.');
/*Augment						--Index 415*/	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('FK', 'Default', 'Augment', 'May only target or affect friendly models.');--2.0 Keywords

/*Get 'em Boys							--Index 416*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Get ''em Boys', 'Spawn four Spikers.  Starting with the Player(s), the Consul and the Party alternate placing Spikers in the dungeon until all four are placed.  Spikers may not be placed within three squares of another Spiker or in the first tile.');

/*9 Lives								--Index 417*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', '9 Lives', 'One Use Only.  When a model with 9 Lives is destroyed, immediately roll 1R.  Remove one wound token for each star rolled.  If no stars are rolled, the model is destroyed as normal.');
/*Active Spawn							--Index 418*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Active Spawn', 'Spawning points with Active Spawn may activate during the Consul Turn in the same manner as 16-Bit Monsters.  When destroyed they grant loot as normal for spawning points.');
/*Active Spawn							--Index 419*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Active Spawn', 'Spawning points with Active Spawn may activate during the Consul Turn in the same manner as 16-Bit Monsters.');
/*Afflict								--Index 420*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Afflict', 'A model with Afflict X causes its target to suffer the listed status effect(s) when it achieves a critical success.');
/*Afflict								--Index 421*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Afflict', 'POISON, IMMOBILE');
/*Afflict								--Index 422*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Afflict', 'FIRE, KNOCKDOWN');
/*Afflict X								--Index 423*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Afflict X', 'A model with Afflict X causes its target to suffer the listed status effect(s) when it achieves a critical.');
/*Afflict X								--Index 424*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Afflict X', 'A model with Afflict X causes its target to suffer the listed status effect(s) when it achieves a critical success.');
/*Alchemy								--Index 425*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Alchemy', 'When a model with Alchemy rolls a heart, it may choose to gain a potion instead.');
/*All-Seeing							--Index 426*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'All-Seeing', 'This Pet''s Master gains Hookshot on its basic Magic attack if it has one and it began its activation within two squares of this Pet.');
/*Alone Forever							--Index 427*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Alone Forever', 'Other friendly models within three squares of a model with Alone Forever must discard the highest result rolled anytime they make a defense roll.');
/*Ambush 								--Index 428*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Ambush', 'When this model spawns or enters play using a Princess Coin, it may be placed on any open square in the dungeon.');
/*Ambush Predator						--Index 429*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Ambush Predator', 'After an enemy model enters a square adjacent to a model with Ambush Predator, the model with Ambush Predator may make a basic attack action against it.');
/*Ammo Dump								--Index 430*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Ammo Dump', 'The Consul places six crystal shell tokens anywhere in the dungeon.  These tokens may not be placed within three squares of another crystal shell token.<br><br>All Heroes gain the following action for the duration of this Boss Fight:  Firing Pin');
/*Angry Walrus							--Index 431*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Angry Walrus', 'At the end of the Consul''s power-up phase, the Consul rolls 1B. If no stars are rolled, nothing happens. If any stars are rolled, the Consul may move the model with Angry Walrus up to one square for each star rolled and then make a basic melee offensive action against any other member of the party in range (Arcade: the Hero''s controller rolls and must move towards and attack the closest other friendly model if stars are rolled).');
/*Animate Soul							--Index 432*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Animate Soul', 'Place a crystal token on target Hero.  When the Hero is destroyed, if the model that placed the crystal is not in play, remove the crystal adjacent to the Hero.  The model spawned in this way suffers three wounds after being placed.');
/*Animate Soul							--Index 433*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Animate Soul', 'Place a crystal token on target Hero.  When the Hero is destroyed, if the model that placed the crystal is not in play, remove the crystal token to spawn the model that placed the crystsal adjacent to the Hero. The model spawned in this way suffers three wounds after being placed.');
/*Kitty Claws							--Index 434*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('FK',  'Arcade', 	'Kitty Claws', 'Beatrix immediately makes one Basic Attack against any enemy model that moves into a square adjacent to Beatrix during its activation.');
/*Another Round							--Index 435*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Another Round', 'During upkeep roll 1B.  For every start rolled Deodric gains one potion.');
/*Apprenticeships						--Index 436*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Apprenticeships', 'Spawn six Forge Gnomes; one within two squares of each dungeon exit in the first tile and one within two squares of each dungeon exit in the last tile.');
/*Arc									--Index 437*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Arc', 'After resolving an action with Arc, choose another model within two squares of the last model targeted and which has not already been targeted.  Resolve the action again, rolling one less dice of the player''s choice against the new target.  Continue choosing new targets in this manner until Arc fails to inflict a wound, no dice remain, or there is no new target in range.');
/*Area Effects							--Index 438*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Area Effects', 'Some actions can hit multiple models all at the same time. These actions are called area effects. To use an area effect, first determine which models are in squares that will be affected. Squares that the user cannot draw line of sight to are not affected. All models that are within the area are considered to be affected simultaneously.\r\n\r\nWith the exception of Burst X, area effects replace the range of an action. If the area effect action requires an offense roll the model using the action makes a single roll. Every model within the area is allowed to make a defense roll. Friendly models, including the user, are not affected by area effects unless they are Augment or Dangerous actions. If a model is affected by two area effects simultaneously the effects are cumulative as long as the actions’ names are different, even if their effects are the same.');
/*Armory								--Index 439*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Armory', 'Equip three Relic Items (in addition to any equipped due to remaining spawning points).');
/*Artillery								--Index 440*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Artillery', 'An action with Artillery may target any square within range, even if no model occupies the square.');
/*As You Wish							--Index 441*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'As You Wish', 'After a treasure with As You Wish is equipped the party must immediately draw two treasure cards and equip them both. While an item with As You Wish is in play, all Heroes with at least one treasure suffer a wound when they achieve a critical success.');
/*Augment 								--Index 442*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Augment', 'May only target or affect friendly models.');
/*Autosave								--Index 443*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Autosave', 'One Use Only. When this model or a friendly model within 2 squares would be destroyed, immediately roll 1G. Remove one wound token for each star rolled. If no stars are rolled, the model is destroyed as normal.');

/*Back Strike							--Index 444*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Back Strike', '+1ST STR If the gang''s target did not activate during the previous Hero Turn.');
/*Backlash								--Index 445*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Backlash', 'When a model with Backlash is targeted by an offensive action and wins the defense roll, the model making the offense roll suffers one wound.  A model may not draw a loot card for destroying a model due to Backlash.');
/*Backlash								--Index 446*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Backlash', 'If a model targeted by an offensive action and wins the defense roll, the model making the offense roll suffers one wound.  A model may not draw a loot card for destroying a model due to Backlash.');
/*Backlash								--Index 447*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Backlash', 'If a model targeted by an offensive action possesses Backlash and wins the defense roll, the model making the offense roll suffers one wound.  A model may not draw a loot card for destroying a model due to Backlash.  (Arcade: A Hero may not inflict more than one wound to monsters in this way per Consul Turn.)');
/*Backlash								--Index 448*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Backlash', 'If a model targeted by an offensive action and wins the defense roll, the model making the offense roll suffers one wound.  A model may not draw a loot card for destroying a model due to Backlash.');
/*Backlash								--Index 449*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Backlash', 'If a model targeted by an offensive action possesses Backlash and wins the defense roll, the model making the offense roll suffers one wound.  A model may not draw a loot card for destroying a model due to Backlash.');
/*Backstabber							--Index 450*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Backstabber', 'When a model with Backstabber suffers a wound, place the wound token on a friendly minion model wihtin three squares instead.');
/*Backstabber							--Index 451*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Backstabber', 'When a model with Backstabber suffers a wound, it may place the wound token on an adjacent friendly model instead.');
/*Bag of Crows							--Index 452*/	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Bag of Crows', 'When a model with Bag of Crows succeeds on a defense roll, spawn one Underdead Crow adjacent to it for each heart rolled (up to a maximum of 4 Underdead Crows in play).');
/*Bane									--Index 453*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Bane', 'A model suffering Bane discards the highest result rolled anytime it makes a defense roll.');
/*Bane									--Index 454*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Bane', 'A monster suffering Bane reduces its ARM by 1ST.');
/*Bane									--Index 455*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Bane', 'A model suffering Bane discards the highest result rolled anytime it makes a defense roll. (Arcade: A monster suffering Bane reduces its ARM by 1ST.)');
/*Battle Without End					--Index 456*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Battle Without End', 'If no mini-boss is in play, spawn a mini-boss selected for this game adjacent to target Hero.  The mini-boss immediately suffers three wounds.  Heroes do not draw treasure for destroying this mini-boss.');
/*Berserk								--Index 457*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Berserk', 'During its activation, a model with Berserk may make a single Melee Attack costing no action points.');
/*Bewitching Song						--Index 458*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Bewitching Song', 'The Consul may move all Heroes 3 squares, using the rules for Compel.');
/*Birds of a Feather					--Index 459*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Birds of a Feather', 'When a model with Birds of a Feather suffers a wound, spawn 2 Underdead Crows adjacent to it.');
/*Biting Wind							--Index 460*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Biting Wind', 'When a model with Biting Wind is destroyed, the model that destroyed it gains ICE at the end of its activation.');
/*Black Ice								--Index 461*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Black Ice', 'Enemy models which end an activation within two squares of this model are moved two squares directly away from the model with Black Ice.');
/*Black Parade							--Index 462*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Black Parade', 'When a model with Black Parade enters play, the Consul spawns two Curse Ravens adjacent to the spawning point icon in the third tile and two adjacent to the spawning point icon in the second tile (four Curse Ravens total).');
/*Bleed									--Index 463*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Bleed', 'When making an offensive roll, a model with Bleed counts any Hearts rolled as both one star and one heart.');
/*Blessed Strike						--Index 464*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Blessed Strike', 'A model with Blessed Strike gains +1ST to all offense rolls it makes for each spent Princess Coin on its card.');
/*Blessing								--Index 465*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Blessing', 'A tile effect with Blessing bestows a positive effect, specified on the tile effect''s card, to models within the tile. Blessings only affect Hero, elite and minion models.');
/*Blood Drinker							--Index 466*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 	'Blood Drinker', 'If a monster with Blood Drinker inflicts at least one wound during a Fight command, remove one wound token from its card.');
/*Blood Drinker							--Index 467*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Blood Drinker', 'When a model with Blood Drinker inflicts a wound, it may remove one wound or status effect token from its card for every heart rolled.');
/*Bluff									--Index 468*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Bluff', 'Models with Bluff gain +1ST to offensive actions taken during another model''s activation.');
/*Bob-omb								--Index 469*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Bob-omb', 'If another Hero activates after this Hero, during the same turn, that Hero gains +1R to the first offense roll it makes that activation.');
/*Bodyguard								--Index 470*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Bodyguard', 'Mini-Bosses and Dungeon Bosses that are adjacent to a monster with Bodyguard may not be targeted with offensive actions which can legally target the monster with Bodyguard.');
/*Bonded Creep							--Index 471*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Bonded Creep', 'This Creep may not be used unless the listed Dungeon Boss is selected for this game.');
/*Bone Collector						--Index 472*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Bone Collector', 'A model with Bone Collector may use hearts it rolls during successful offensive actions on Pets as well as Heroes.');
/*Boo Booty								--Index 473*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Boo Booty', 'Boo Booty cannot be spawned, instead they enter play when their treasure card is drawn.');
/*Born Lucky							--Index 474*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Born Lucky', 'A model with Born Lucky may reroll one heart when it rolls dice.');
/*Bouncing Betty						--Index 475*/	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Bouncing Betty', 'A model with Bouncing Betty may enter squares occupied by other models (and other models may enter squares containing a model with Bouncing Betty).  As soon as a model with Bouncing Betty shares a square with an enemy model, destroy it and trigger Volatile.  When a model with Bouncing Betty activates, roll 1R and move it a number of squares equal to the number of stars rolled towards the closest Hero.  If there are ever 12 models with Bouncing Betty in play, immediately destroy all of them (this triggers Volatile).');
/*Bound									--Index 476*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Bound', 'When a monster with Bound is destroyed, a SUPER on the same tile may instead choose to suffer one wound and prevent the monster from being destroyed.');
/*Bound									--Index 477*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Bound', 'When a monster with Bound is destroyed, a SUPER on the same tile may instead choose to suffer one damage and prevent the monster from being destroyed; remove all wound tokens from the monster with Bound.');
/*Broken Heart							--Index 478*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Broken Heart', 'When a model with Broken Heart rolls hearts during a successful attack, it may not use them to heal friendly models. Instead, it must choose one friendly model to suffer a wound for each heart rolled.');
/*Bruiser								--Index 479*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Bruiser', '+1ST STR if a model with Bruiser is in the gang.');
/*Brutal Strike							--Index 480*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Brutal Strike', 'When this model wins an offense roll, add three stars to its total.');
/*Brutal Strike							--Index 481*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Brutal Strike', 'When this model wins an offense roll, add +3ST to its total.');
/*Brutal Strike							--Index 482*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Brutal Strike', 'When this model wins an offense roll, it gains +3ST to its total.');
/*Brutal Strike							--Index 483*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Brutal Strike', 'When this model wins an offense roll, add +3ST to its total.');
/*Brutality Aura						--Index 484*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Brutality Aura', 'All models, friendly or enemy, within 2 squares gain +1st STR.');
/*Brutality Aura						--Index 485*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Brutality Aura', 'All models, friendly or enemy, within two squares of a model with Brutality Aura gain +1ST STR.');
/*Brutality Aura						--Index 486*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Brutality Aura', 'All models, friendly or enemy, that are within two squares of a model with Brutality Aura gain +1ST STR.');
/*Bulldozer								--Index 487*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Bulldozer', 'A model with Bulldozer may move through enemy models, and treats difficult terrain and structure squares as open squares. All non-blessing tile effects in those squares are ignored.');
/*Bully									--Index 488*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Bully', 'A monster with Bully always targets the Hero with the least wrath with its commands.');
/*Bumper Shell							--Index 489*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Bumper Shell', 'Make a Melee Attack against every Hero in the dungeon, regardless of its location.  Any model which is wounded must discard one equipped equipment card.');
/*Burn, Insects!						--Index 490*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Burn, Insects!', 'Enemy models within two squares that resolve Fire during their upkeep must discard two equipment cards from the backpack or suffer an additional wound.');
/*Burning Blades						--Index 491*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Burning Blades', 'All elite and minion monsters gain the ability FIRE.');
/*Burrow								--Index 492*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Burrow', 'A monster with Burrow may move through walls, and treats difficult terrain and structure squares as open squares.  All non-blessing tile effects in those squares are ignored.');
/*Burrow								--Index 493*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Burrow', 'A model with Burrow may move through walls, and treats difficult terrain and structure squares as open squares.  All non-blessing tile effects in those squares are ignored.');

/*Call Of The Deep						--Index 494*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Call Of The Deep', 'When a model with Call Of The Deep succeeds with an attack, it may spawn one Skull Point worth of 8-Bit monsters per heart rolled within 3 squares of it.');
/*Caught Red Handed						--Index 495*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Caught Red Handed', 'The Consul selects one Hero that is not on Kringle''s Nice List.  The selected Hero shapeshifts into a Naughty of the Consul''s choice.');
/*Cave-In								--Index 496*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Cave-In', 'Each Hero must choose to suffer either two wounds or Immobile.');
/*Chained to Me							--Index 497*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Chained to Me', 'Enemy models that make an attack controlled by this model gain +1G to the roll.');
/*Challenge								--Index 498*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 	'Challenge', 'A model with Challenge may not suffer wounds from actions, unless the action was taken by the Hero with the most wrath (it still suffers effects such as Push and status effects normally).');
/*Challenge								--Index 499*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Challenge', 'When a boss with Challenge spawns, the Party must choose one Hero as their Champion. No model except the Champion may deal damage to the boss, though the boss may suffer other effects (such as Push or status effects) caused by other models. The boss gains +1R to all offensive actions it takes that target the Champion. If the Champion is destroyed, the Party must select another Hero to become the Champion.');
/*Challenge								--Index 500*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Challenge', 'When a boss with Challenge spawns, the party must choose one Hero as their Champion. No model except the Champion may deal wounds to the boss with actions, though the boss may suffer other effects (such as Push or status effects) caused by other models. If the Champion is destroyed, the Party must select another Hero to become the Champion.');
/*Charge								--Index 501*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 	'Charge', 'When a model with Charge uses a Lance area effect, after resolving all other effects of the Lance, place the model in an unoccupied square that was affected by the Lance, and which is as close as possible to the Hero with the most wrath.');
/*Charge								--Index 502*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Charge', 'When a model with Charge uses a Lance area effect, after resolving all other effects of the Lance, the model may be placed in any unoccupied square that was affected by the Lance for free.');
/*Charge Through						--Index 503*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Charge Through', 'All Heroes immediately suffer a melee attack with 5R STR, regardless of range and LOS.');
/*Children of Decay						--Index 504*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Children of Decay', 'The Consul selects a Hero and spawns a Kodead adjacent to it.  Repeat this until a Kodead has spawned adjacent to each Hero or there are six Kodeads in play.');
/*Clever								--Index 505*/	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Clever', 'When a Boss Sighting space is reached, a model with Clever may suffer a wound to cancel the Boss Sighting.'); 
/*Clever								--Index 506*/	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 	'Clever', 'When a Challenge card is drawn with a Trap effect, a model with Clever may suffer a wound to cancel the Trap effect.');
/*Coghammer								--Index 507*/	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Coghammer', 'When a model with Coghammer rolls a heart, it may suffer a wound to turn one die that rolled a heart to any facing of its choice.');
/*Cold Fury								--Index 508*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Cold Fury', 'After any Waystone Creep suffers damage during the Hero turn, a model with Cold Fury may immediately take the Stinging Wind action.');
/*Come Hither							--Index 509*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Come Hither', 'All Heroes suffer Compel 2.');
/*Come, My Loves						--Index 510*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Come, My Loves', 'Spawn Spiteful Cherubs anywhere in the dungeon until there are four in play.');
/*Consul's Wrath, The					--Index 511*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Consul''s Wrath, The', 'This model gains +1R to all offense rolls.');
/*Consuming Greed						--Index 512*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Consuming Greed', 'Whenever the party draws treasure, a model with Consuming Greed must equip the treasure, unless it would cause the Black Pearl to be discarded.');
/*Convergence With The Goddess			--Index 513*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Convergence With The Goddess', 'If the party contains one or more Heroes with Convergence With The Goddess, during the Hero Power-Up phase, the party may discard four loot from the backpack to select a Princess Coin that was not used for this game and spend it to permanently place it on any one Hero''s card, this Princess Coin grants the Hero +1ST to defense rolls.');
/*Corpse Stench							--Index 514*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Corpse Stench', 'When a model with Corpse Stench suffers damage, all adjacent enemy models suffer Slow.');
/*Count of Seven						--Index 515*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Count of Seven', 'When Onryo spawns, begin tracking the number of Hero activations that occur during the Boss Fight.  At the end of the seventh activation, remove one Princess Coin from the backpack.  Then begin the count again.');
/*Counterstrike							--Index 516*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 	'Counterstrike', 'When a model with Counterstrike suffers a wound, it may immediately make a single Melee Attack targeting the model which inflicted the wound, so long as the model is within range.');
/*Counterstrike							--Index 517*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 	'Counterstrike', 'When a model with Counterstrike suffers a wound, it may immediately make a single Basic Attack targeting the model which inflicted the wound, so long as the model is within range.');
/*Counterstrike							--Index 518*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Counterstrike', 'When a model with Counterstrike suffers a wound, it may immediately make a single Melee Attack targeting the model which inflicted the wound, so long as the model is within range.');
/*Crush									--Index 519*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Crush', 'A model with Crush gains Massive Damage if its target was suffering Ice when it was targeted.');
/*										--Index 520*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('', '', '', '');
/*Crystal Curse							--Index 521*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Crystal Curse', 'When a model with Crystal Curse succeeds with an offensive action, apply one random status effect token to the target for each heart the model with Crystal Curse rolled.');
/*Crystal Shaping						--Index 522*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Crystal Shaping', 'At the start of this model''s activation it may discard one equipment card from the backpack in order to gain one of the following until the start of its next activation, depending on the equipment''s slot:<br>Citrine: +1AC<br>Emerald:  +2MV<br>Ruby:  +1R WILL<br>Sapphire: +1R ARM.');
/*Cursed								--Index 523*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Cursed', 'Equipment with Cursed must be equipped during Power-Up if any Hero has an available slot, and cannot be removed or discarded unless the model is destroyed.');

/*Daemonus								--Index 524*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Daemonus', 'If Daemonus is not in play, spawn Daemonus within six squares of the Midnight Queen.');
/*Dance Party							--Index 525*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Dance Party', 'If another Hero activates after the equipped hero during the same turn, that hero gains:  +2 Movement Points,  +1 Action Point,  +1R DEX,  +1R WILL,  during that activation.');
/*Dance Party							--Index 526*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Dance Party', 'If another Hero activates after this Hero, during the same turn, that Hero gains:  +2 Movement Points,  +1 Action Point,  +1R DEX,  +1R WILL,  during that activation.');
/*Dark Defender							--Index 527*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Dark Defender', 'The dungeon boss may not be targeted with offensive actions while a model with Dark Defender is in play.');
/*Dark Legion Spawn						--Index 528*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Dark Legion Spawn', 'This elite is also a spawning point, and it may not be placed on the first tile during setup.  After placing it during setup, spawn five Undead Legionaires bonded to it.  When this elite receives the spawn command, roll 1B1R and spawn one Necromutant Solo for each star rolled.  When this elite receives the reinforce command, spawn Undead Legionaires until it has five bonded Undead Legionaires.');
/*Dark Nexus							--Index 529*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Dark Nexus', 'This spawning point may not begin on the first or the second tile.');
/*Dark Radiance							--Index 530*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Dark Radiance', 'All offense rolls and defense rolls made against a model with Dark Radiance reduce the result by 1ST.');
/*Dark Reflection						--Index 531*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Dark Reflection', 'Boss sightings always affect the tile this Hero is on, in addition to any tiles listed by the Mighty Monster Chart.<br>(Arcade: During Consul Power-Up, look at the top card of the challenge deck. If it has a Trap effect, resolve it immediately, then discard it with no further effect.)');
/*Dark Reflection						--Index 532*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Dark Reflection', 'Boss sightings always affect the tile this Hero is on, in addition to any tiles listed by the Mighty Monster Chart.<br>(Arcade: During Consul Power-Up, look at the top card of the challenge deck. If it has a Trap effect, resolve it immediately. Then discard it with no further effect.)');
/*Deadly Defense						--Index 533*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Deadly Defense', 'This model may score critical successes on defense rolls. If it does, the attacker suffers a wound.');
/*Deadly Defense						--Index 534*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Deadly Defense', 'This model may score criticals on defense rolls. If it does, the attacker suffers a wound.');
/*Death Curse							--Index 535*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Death Curse', 'Roll 1B.  The Consul may inflict a number of wounds on the Heroes equal to the number of stars rolled.  The wounds must be distributed as evenly as possible.');
/*Death Curse							--Index 536*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 	'Death Curse', 'When one or more models in this gang ends a move adjacent to a Hero, the party must select one model in the gang with Death Curse.  The selected model is destroyed and the party rolls 1G.  Apply one of the below status effects to the adjacent Hero depending on the roll:<br>Heart/Potion:  Bane<br>1ST:  Hex<br>2ST: Ice<br>3ST: Poison<br>4ST:  Immobile');
/*Death Curse							--Index 537*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Death Curse', 'When a model with Death Curse is destroyed, roll 1G and place the corresponding status effect token on the square the model had occupied.  If a Hero enters the square with the status effect token, remove the token and the Hero gains the status effect at the end of the current activation:<br>Heart/Potion:  Bane<br>1ST:  Hex<br>2ST: Ice<br>3ST: Poison<br>4ST:  Immobile');
/*Death Lord							--Index 538*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 	'Death Lord', 'All other Undead models in play gain +2ST STR.');
/*Death Lord							--Index 539*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 	'Death Lord', 'When a model with Death Lord spawns, randomly select a spawning point that was destroyed this game and spawn all gangs listed on it within 3 squares of the model with Death Lord.');
/*Death Lord							--Index 540*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Death Lord', 'While a model with Death Lord is in play, all Undead monsters without the Death Lord ability gain +1G to all rolls.');
/*Death Lord							--Index 541*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Death Lord', 'While a model with Death Lord is in play, all Undead monsters without the Death Lord ability gain +1G to all offensive rolls.  When a model with Death Lord activates, spawn one Kodead withint two squares of it.');
/*Death Lord							--Index 542*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Death Lord', 'All Undead models within four squares of a model with Death Lord gain +1B to all offense rolls.');
/*Defender								--Index 543*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Defender', 'Models without Defender that are adjacent to a friendly model with Defender cannot be targeted by offensive actions.');
/*Defender								--Index 544*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Defender', 'When enemy models declare a basic attack action if the action can target a model with Defender, it must target a model with Defender.');
/*Defenseless							--Index 545*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Defenseless', 'When a model with Defenseless is wounded, a friendly adjacent model may choose to be wounded instead.');
/*Demonic Possession					--Index 546*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Demonic Possession', 'The Consul selects a Hero to be possessed.  The possessed Hero is controlled by the Consul and counts as an 8-Bit monster worth three skull points for all purposes.  It activates on the Consul turn and may not use other Heroes'' potions or equipment.  If the possessed Hero is destroyed it permanently returns to the control of the party.  The Hero''s original controller brings it back into play during the turn''s power-up adjacent to any other Hero without spending a Princess Coin.');
/*Despair								--Index 547*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Despair', 'Enemy models within two squares of a model with Despair reduce the result of all defense rolls by 1ST.');
/*Dibs									--Index 548*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 	'Dibs', 'When a Hero on this tile discards a loot card due to Yoink!, place a crystal token on this model.  This model gains +1ST STR for each crystal token on it.');
/*Dibs									--Index 549*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 	'Dibs', 'When a Hero on this tile discards a loot card due to Piracy, place a crystal token on this model.  This model gains +1ST STR for each crystal token on it.');
/*Dibs									--Index 550*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Dibs', 'When a Hero on this tile discards a loot card due to the Yoink! ability, a model with Dibs may choose to equip the discarded loot as if it were a Hero.  Equipped loot is discarded when this model is destroyed.');
/*Dibs									--Index 551*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Dibs', 'When a Hero on this tile discards a loot card due to the Piracy ability, a model with Dibs may choose to equip the discarded loot as if it were a Hero.');
/*Difficulty Rating						--Index 552*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Difficulty Rating', 'If the party is unable to beat this boss with the usual number of Princess Coins, they may add X addtional Princess Coins the next time they face this boss.');
/*Difficulty Rating 1					--Index 553*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Difficulty Rating 1', 'If the party is unable to beat this boss with the usual number of Princess Coins, they may add 1 addtional Princess Coins the next time they face this boss.');
/*Difficulty Rating 2					--Index 554*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Difficulty Rating 2', 'If the party is unable to beat this boss with the usual number of Princess Coins, they may add 2 addtional Princess Coins the next time they face this boss.');
/*Difficulty Rating 3					--Index 555*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Difficulty Rating 3', 'If the party is unable to beat this boss with the usual number of Princess Coins, they may add 3 addtional Princess Coins the next time they face this boss.');
/*Discipline							--Index 556*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Discipline', 'While on the same tile as another gang or solo monster, a monster with Discipline giains +1ST STR and +1ST ARM.');
/*Discipline							--Index 557*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Discipline', 'A model with Discipline gains +1B to all rolls while it is adjacent to at least one other friendly model.'); 
/*Divine Guidance						--Index 558*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Divine Guidance', 'When a challenge card with a Trap effect is drawn, this model may discard this treasure to prevent the Trap effect from happening.');
/*Do It For Me							--Index 559*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Do It For Me', 'When a Hero within four squares of a model with Do It For Me activates, the Hero must roll its WILL.  On a roll of 0 stars, the Consul controls the Hero''s first action and first three moves of the activation.  The remainder of the activation is taken normally.');
/*Do It For Me?							--Index 560*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 	'Do It For Me', 'When a Hero within six squares of a model with Do It For Me? activates, the Hero must roll its WILL.  On a roll of 0 stars, the Hero must take its first three moves to move as close to the closest other Hero as possible and then use its first action to target that Hero with a basic attack action.  The rest of the activation is taken normally.');
/*Do Not Fight							--Index 561*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Do Not Fight', 'All Heroes suffer HEX.');
/*Dragged To The Depths					--Index 562*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Dragged To The Depths', 'When a model with Dragged To The Depths is destroyed, the model that destroyed it must roll 1R.  If no stars are rolled, it suffers one wound.');
/*Dread									--Index 563*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Dread', 'A model with Dread gains +1ST to all offense rolls if it is currently benefitting from Stealth.');
/*Dungeon Map							--Index 564*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Dungeon Map', 'During setup, after all dungeon tiles have been selected, Star Princess Candy may determine each tile''s order and orientation.');

/*Eat Crow								--Index 565*/	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Eat Crow', 'When a model with Eat Crow is destroyed, all adjacent enemy models must roll their WILL. If they roll 2 or fewer stars, they suffer BANE.');
/*Elemental Affinity					--Index 566*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Elemental Affinity', 'For each model with Elemental Affinity choose one element from the Elemental Affinity card at the beginning of the game. That model gains the chosen element''s abilities. If the model is a spawning point, all models spawned from that point gain the chosen elements abilities. Paired spawning points must choose the same element.');
/*Elemental Affinity					--Index 567*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Elemental Affinity', 'At the beginning of the game, a model with Elemental Affinity must choose one element from the Elemental Affinity card. That model gains the chosen element''s abilities. If the model is a spawning point, all models spawned from that spawning point gain the chosen element''s abilities. Paired spawning points must choose the same element.');
/*Emergency Supply						--Index 568*/	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Emergency Supply', 'A Pet with Emergency Supply may equip one loot card as if it were a Hero.');
/*Emergency Supply						--Index 569*/	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('', '', '', '');
/*Eternal Flame							--Index 570*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Eternal Flame', 'Enemy models within 2 squares and LOS of a model with Eternal Flame do not remove the Fire status effect at the end of their activation.');
/*Eternal Flame							--Index 571*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Eternal Flame', 'Enemy models on the same tile as a model with Eternal Flame may only remove the Fire status effect when a heart is rolled (not at the end of their activation or through any other effect).');
/*Excess Ammo							--Index 572*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Excess Ammo', 'When a model with Excess Ammo discards a crystal shell token as part of an action, roll 1R on a roll of two or more stars, the token is not discarded.');
/*Excessive Armor						--Index 573*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Excessive Armor', 'When this boss spawns, starting with the last tile and working backwards, place on crystal token adjacent to each SPAWNPOINT square.  Repeat this until there are a number of crystal tokens equal to the number of Heros.  A Hero may place an adjacent crystal token onto its card by taking an Interact action.  Heroes without a crystal token may not cause the dungeon boss to suffer wounds with offensive actions.');
/*Experimental Calculations				--Index 574*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Experimental Calculations', 'Nikolai Ten draws two treasure cards.  Choose one card and shuffle the other back into the deck.  Nikolai Ten gains the effects listed on the chosen card until the beginning of the next activation, then discards the card.  Only Nikolai Ten may use Experimental Calculations.');
/*Extra Sparkly							--Index 575*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Extra Sparkly', 'When a model with Extra Sparkly ends its activation, it may gain two wrath.');
/*Eye is Open, The						--Index 576*/	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Eye is Open, The', 'After an enemy model moves, a model with The Eye is Open may roll 1B.  If any stars are rolled, the model with The Eye is Open may make a basic magic attack against it (so long as the enemy is within range and LOS as normal).');

/*False Security						--Index 577*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'False Security', 'The model equipped with Cursed Remains suffers Bane, which can only be removed when the model dies. The model does not gain a Princess Coin.');
/*Favors of the Goddess					--Index 578*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Favors of the Goddess', 'Princess Coins on this model''s card grant it +1R to defensive rolls instead of +1ST.');
/*Feed Me								--Index 579*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Feed Me', 'During upkeep, if a monster with Feed Me is suffering any wounds, destroy one minion within two squares of the model and remove one would token.');
/*Feed Me								--Index 580*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Feed Me', 'Once per activation, a model with Feed Me may remove one friendly model within melee range from play to remove one wound or one status effect token.');
/*Feint									--Index 581*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Feint', 'When a model with Feint makes an offensive action they may choose one dice from their target''s defense roll and force them to reroll the result.  (Arcade: Decrease ARM of target model by +1ST.)');
/*Feint									--Index 582*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Feint', 'When a model with Feint makes an offensive action decrease the ARM of target model by 1ST.');
/*Feint									--Index 583*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Feint', 'When a model with Feint makes an offensive action they may choose one dice from their target''s defense roll and force them to reroll the result.');
/*Feint									--Index 584*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Feint', 'When a model with Feint makes an offensive action, it may choose one dice from the target''s defense roll and force them to reroll the result.');
/*Feint									--Index 585*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Feint', 'When a model with Feint makes an offensive action, it may choose one dice from the target''s defense roll and force them to reroll the result. (Arcade: Decrease ARM of target model by 1ST.)');
/*Ferocious Hoot						--Index 586*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Ferocious Hoot', 'At the end of this model''s activation, spawn two Yowlings within four squares of this model, up to a maximum of six Yowlings in play.');
/*Fertilizer							--Index 587*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Fertilizer', 'This model immediately shapeshifts back into its original form if a friendly model in an adjacent square takes the Interact action and discards two loot from the Backpack.');
/*Fire									--Index 588*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Fire', 'A model suffering Fire suffers one wound during its upkeep.');
/*Fire Aura								--Index 589*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Fire Aura', 'Monsters with CITRINEAFFINITY that are within two squares of a model with Fire Aura gain FIRE.');
/*Fire Storm							--Index 590*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Fire Storm', 'All Heroes suffer FIRE.');
/*First Stone, The						--Index 591*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'First Stone, The', 'A model with The First Stone gains +1B to all offensive rolls for each wound it is suffering, to a maximum of +3B.');
/*Fixed Form							--Index 592*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Fixed Form', 'A shapeshift with Fixed Form may not shapeshift into its original form during a unique command.');
/*Fixed Form							--Index 593*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Fixed Form', 'A shapeshift with Fixed Form may not shapeshift into its original form during its upkeep.');
/*Flaming								--Index 594*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Flaming', 'When a model with Flaming ends its activation, all adjacent enemies suffer Fire.');
/*Flammable								--Index 595*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Flammable', 'When a model with Flammable is targeted by an action that causes FIRE, the Flammable model suffers FIRE even if it wins the defense roll.');
/*Fly									--Index 596*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Fly', 'A model with Fly treats difficult terrain, chasm, and structure squares as open squares.  All non-blessing tile effects in those squares are ignored.  Structure squares do not block line of sight to or from models with Fly.');
/*Fodder								--Index 597*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Fodder', 'When an Elite within 2 squares, that has no bonded minions, suffers a wound, apply the wound to this model instead as if it were one of the Elite''s bonded minions.');
/*For The Crown							--Index 598*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'For The Crown', 'When a model with For The Crown is destroyed it makes two basic 0MI attacks before being removed from play.');
/*For The Pirate Queen!					--Index 599*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'For The Pirate Queen!', 'Ijin Oni gain Frenzy for the remainder of the game.  (A model with Frenzy gains +1R on offensive rolls against any model that is suffering a wound.)');
/*For Unlawful Carnal Knowledge			--Index 600*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'For Unlawful Carnal Knowledge', 'All Spiteful Cherubs in play gain 1SW to their strength (they may now make basic melee attacks normally).');
/*Forced Shift							--Index 601*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Forced Shift', 'When a model with Forced Shift is destroyed, instead of being removed from play it immediately Shapeshifts.');
/*Forest Awakens, The					--Index 602*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Forest Awakens, The', 'The Consul may spawn up to 4 skull points of monsters from the spawning pool anywhere in the dungeon.');
/*Forest Blessings						--Index 603*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Forest Blessings', 'All other monsters on the same tile as a model with Forest Blessings gain +1ST STR.');
/*Forest's Vengeance The				--Index 604*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Forest''s Vengeance The', 'This effect does not occur during Boss Sightings.  For the remainder of the game, all monsters except for Mother Noctua gain +1R to all rolls.');
/*Forge Master							--Index 605*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 	'Forge Master', 'When a model with Forge Master spawns, draw and equip two treasure cards to it.  The model gains any ARM bonuses.  Any other stat bonuses are considered to be applied to the model''s STR.  When a model with Forge Master needs to roll due to the dice bonuses on its treasure, the player to the active player''s left rolls.  The model with Forge Master ignores all abilities and actions on the treasure.');
/*Forge Master							--Index 606*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Forge Master', 'This dungeon boss may equip up to two Relic Items per slot.');
/*Formless								--Index 607*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Formless', 'At the beginning of this model''s activation it may increase one attribute by +1B.  This bonus lasts until it is activated again.');
/*Fortify								--Index 608*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Fortify', 'A model with Fortify gains +1B ARM for each enemy adjacent to them, to a maximum of +3B ARM.');
/*Found a Shiny							--Index 609*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Found a Shiny', 'When a model with Found A Shiny rolls a critical success, draw one loot and place it into the backpack!');
/*Free Coin								--Index 610*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Free Coin', 'When a Hero with Free Coin suffers a wound that removes it from play, it is immediately returned to play as though a Princess Coin was spent.<br>(No Princesss Coin is used to activate Free Coin and no Princess Coin is placed on its card.)');
/*Freed In Death						--Index 611*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 	'Freed In Death', 'When a model with Freed In Death is destroyed, the closest minion model is also destroyed.');
/*Freed In Death						--Index 612*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Freed In Death', 'When a model with Freed In Death is destroyed, the party may choose one monster in range.  The model with Freed In Death makes a melee attack against the chosen monster before being removed.');
/*Frenzy								--Index 613*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 	'Frenzy', 'A monster or gang with Frenzy gains +1ST STR against any model that is suffering a wound.');
/*Frenzy								--Index 614*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 	'Frenzy', 'A monster or gang with Frenzy gains +1ST against any model that is suffering a wound.');
/*Frenzy								--Index 615*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Frenzy', 'A Model with Frenzy gains +1R on offensive rolls against any model that is suffering one or more wounds.');
/*Frenzy								--Index 616*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Frenzy', 'A model with Frenzy gains +1R on offensive rolls against any model that is suffering a wound.');
/*Fresh Grave							--Index 617*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Fresh Grave', 'Kodeads may be spawned from Fresh Grave Tile Effects instead of Rattlebones.');
/*Frostfang								--Index 618*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Frostfang', 'A model with Frostfang gains +1G to offensive rolls while targeting a model suffering ICE.');
/*Frosty Imps							--Index 619*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Frosty Imps', 'Spawn Frost Imps within three squares of the dungeon boss until there are six Frost Imps in play.');
/*Frosty Imps							--Index 620*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Frosty Imps', 'When a model with Frosty Imps spawns, spawn Frost Imps within three squres of it until there are six Frost Imps in play.'); 
/*Frozen Prison							--Index 621*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Frozen Prison', 'While this Relic is attached to a Hero, the Hero must roll 1B before taking an action.  If no stars are rolled, the action automatically fails.  The Hero may choose to suffer one wound to reroll the die.');
/*Fueled by Fire						--Index 622*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Fueled by Fire', 'A model with Fueled by Fire adds 1R to all offensive rolls for each model suffering Fire.');
/*Fungal Fury							--Index 623*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Fungal Fury', 'Enemy models that end a Push within three squares and LoS of one or more models with Fungal Fury suffer one wound.');
/*Furious Bloom							--Index 624*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Furious Bloom', 'This effect only occurs during Boss Sightings.  The Consul may spawn up to 4 skull points of monsters from the spawning pool in each tile affected by the Boss Sighting.  These monsters may spawn anywhere in the tile.');
/*Fury									--Index 625*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Fury', 'A model with Fury gains +1ST STR for each wound it is currently suffering.');
/*Fury									--Index 626*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Fury', 'A model with Fury gains +1B to all offense rolls for each wound it is currently suffering.');
/*Fury									--Index 627*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Fury', 'A model with Fury gains +1B STR to all offense rolls for each wound it is currently suffering.');

/*Gatekeeper							--Index 628*/	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Gatekeeper', 'When a model with Gatekeeper is spawned, select the closest doorway to the spawning point that connects two tiles.  The model with Gatekeeper is spawned in the selected doorway.  Move any models in the way up to one space.  Then, the model with Gatekeeper immediately makes one basic melee attack against all adjacent enemy models.');
/*Ghost									--Index 629*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Ghost', 'A model with Ghost ignores walls for the purpose of line of sight and movement.');
/*Ghost									--Index 630*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Ghost', 'A model with Ghost ignores walls and structures for the purpose of line of sight and movement.');
/*Ghost									--Index 631*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Ghost', 'A model with Ghost ignores walls and structures for the purpose of line of sight and movement.');
/*Ghost Charge							--Index 632*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Ghost Charge', 'When this treasure is equipped place 4R on it. Whenever this model makes a roll, it may remove any number of dice from this treasure and add them to the roll. Once the dice have been used they are removed from this card permanently.');
/*Ghostmancer							--Index 633*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Ghostmancer', 'Whenever a model with Ghostmancer inflicts a wound, place a Ghost model adjacent to the wounded model.');
/*Glimpse The Future					--Index 634*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Glimpse The Future', 'While a model with Glimpse the Future is in play, immediately discard and redraw any cards drawn from the Treasure Deck which are not Treasure.');
/*Go For The Eyes!						--Index 635*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Go For The Eyes!', 'Spawn 1 Underdead Crow adjacent to each Hero, until there is a maximum of 4 Underdead Crows in play.');
/*Grabby								--Index 636*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Grabby', 'A model that is adjacent to an enemy model with Grabby may not move.');
/*Grave Spawn							--Index 637*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Grave Spawn', 'This Pet may not be brought into play with the Summon Pet action. Instead, if this Pet was selected by a Hero, the Hero may suffer one damage to spawn one Pet Ghost adjacent to any other Hero before that Hero is destroyed.');
/*Grave Spawn							--Index 638*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Grave Spawn', 'This Pet may not be brought into play with  Summon Pet. Instead, when another Hero is destroyed, this Pet''s Master may suffer one wound to spawn one Ghost adjacent to the Hero before it is removed.');
/*Grave Visions							--Index 639*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Grave Visions', 'When this model is destroyed, place three red dice on this treasure. This model may discard 1R from the Crimson Watcher when it makes any roll to add 1R to the roll.');
/*Guardian								--Index 640*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Guardian', 'Adjacent Heroes double their Defense bonuses from Princess Coins.');

/*Have A Heart							--Index 641*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Have A Heart', 'A model with Have A Heart benefits from hearts it rolls on failed actions as well as successful actions.');
/*Heal									--Index 642*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Heal',	'A model affected by Heal may remove a number of wound tokens or a number of status effect tokens, in any combination, equal to the value of X.');
/*Healer								--Index 643*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Healer', 'When a model with Healer rolls a potion, it may choose to gain a heart instead.');
/*Heart of the Forge					--Index 644*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Heart of the Forge', 'When this Relic item is equipped, this model may Heal 3. Then all enemy models in Wave 4 suffer 1 wound and FIRE.');
/*Hero's Bane							--Index 645*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Hero''s Bane', 'A model with Hero''s Bane gains +1ST STR while making a basic melee attack for each Ghostflame adjacent to the target.');
/*Heroic Mob							--Index 646*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Heroic Mob', 'Friendly models within two squares and Line of Sight gain Mob.');
/*Hex									--Index 647*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Hex', 'A model suffering Hex discards the highest result rolled anytime it makes an offense roll.');
/*Hex									--Index 648*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Hex', 'A monster suffering Hex reduces its STR by 1ST.');
/*Hex									--Index 649*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Hex', 'A model suffering Hex discards the highest result rolled anytime it makes an offense roll. (Arcade: A monster suffering Hex reduces its STR by 1ST.)');
/*Hex Aura								--Index 650*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Hex Aura', 'Monsters with RUBYAFFINITY that are within two squares of a model with Hex Aura gain Hex.');
/*Hidden								--Index 651*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('FK', 'Default', 'Hidden', 'Models Spawned from a spawning point with Hidden may be placed anywhere on the tile, instead of only within 2 squares.');
/*Hold Them!							--Index 652*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Hold Them!', 'Spawn one Spiteful Cherub adjacent to each Hero in play.');
/*Holiday Madness						--Index 653*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Holiday Madness', 'After a model with Holiday Madness suffers wounds, roll 1R and apply one of the following effects:<br><br>0ST Potion: This model suffers an additional wound.<br><br>One Star: The closest other Hero suffers one wound.<br><br>Two stars, Three stars: The party draws one loot and places it in the Backpack.');
/*Holy									--Index 654*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Holy', 'A model with Holy may reroll a single dice when making offensive actions against undead, demons, or nether models.');
/*Holy									--Index 655*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Holy', 'A model with Holy may reroll a single dice when making offensive actions which target undead, demons, or nether models.');
/*Hookshot								--Index 656*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Hookshot',	'/* Actions with Hookshot do not require line of sight to target a model. Range must still be counted around spaces that block line of sight, such as walls and structures.*/'); --Not sure if description is correct
/*Hookshot								--Index 657*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Hookshot',	'Actions with Hookshot do not require line of sight to target a model. Range must still be counted around walls and structures.');
/*Howling Vengeance						--Index 658*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Howling Vengeance', 'All other Ijin on this tile gain +1R on attack rolls for every three wounds on a model with Howling Vengeance.');
/*Hubris								--Index 659*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade',	'Hubris', 'A model with Hubris gains +1ST STR for every equipment card equipped on its target.');
/*Hubris								--Index 660*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade',	'Hubris', 'When making a Melee Attack, a model with Hubris gains +1ST STR for every equipment card equipped on its target.');
/*Hubris								--Index 661*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore',	'Hubris', 'When making a Melee Attack, a model with Hubris gains +1B STR for every equipment card equipped on its target.');
/*Hunger								--Index 662*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Hunger', 'When a model with Hunger rolls a Heart, no other model may benefit from its effect unless the model with Hunger is not suffering any wounds.');
/*Hunter								--Index 663*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Hunter', 'A model with Hunter may reroll a single die when making offensive actions which target spider, gnoll, or orc models.');
/*Hunter's Mark							--Index 664*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Hunter''s Mark', 'Place a crystal token on the closest enemy model.  Friendly models attacking the model with the crystal token gain +1ST STR.  Only one frinedly Mark token may be in play at one time and it may not be removed until the target is destroyed or Mark is used again.');
/*Hunter's Mark							--Index 665*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Hunter''s Mark', 'Place a crystal token on the target.  Friendly models attacking the target gain +1B to their offense rolls.  Only one frinedly Mark token may be in play at one time and it may not be removed until the target is destroyed or Mark is used again.');

/*I Know A Shortcut						--Index 666*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'I Know A Shortcut', 'You may discard the Devil Island Map at any time to select any one tile and rotate it up to 180 degrees.');
/*I Know Nothing						--Index 667*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'I Know Nothing', 'A model with this ability may not use the Open Chest action.');
/*Ice									--Index 668*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Ice', 'A model suffering Ice may not use unique actions.');
/*Illumination							--Index 669*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Illumination', 'Models that target an enemy model within 3 squares of a friendly model with Illumination may reroll a single dice.');
/*Illumination							--Index 670*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Illumination', 'Models that target an enemy model within 3 squares of a friendly model with Illumination may reroll a single dice.');
/*Illusionary Double					--Index 671*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Illusionary Double', 'When a model with Illusionary Double suffers a wound, place one crystal token on its card. It may never have more than one crystal token. When the model is affected by an action that requires a defense roll, it may remove one crystal token to automatically win the roll.');
/*Immobile								--Index 672*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Immobile', 'A model affected by Immobile may not move during its next activation.');
/*Immune: Bane							--Index 673*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Immune: Bane', 'A model with Immune: Bane ignores and immediately removes all counters and/or the affects of Bane.');
/*Immune: Fire							--Index 674*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Immune: Fire', 'A model with Immune: Fire ignores and immediately removes all counters and/or the affects of Fire.');
/*Immune: Hex							--Index 675*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Immune: Hex', 'A model with Immune: Hex ignores and immediately removes all counters and/or the affects of Hex.');
/*Immune: Ice							--Index 676*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Immune: Ice', 'A model with Immune: Ice ignores and immediately removes all counters and/or the affects of Ice.');
/*Immune: Immobile						--Index 677*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Immune: Immobile', 'A model with Immune: Immobile ignores and immediately removes all counters and/or the affects of Immobile.');
/*Immune: Knockdown						--Index 678*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Immune: Knockdown', 'A model with Immune: Knockdown ignores and immediately removes all counters and/or the affects of Knockdown.');
/*Immune: Poison						--Index 679*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Immune: Poison', 'A model with Immune: Poison ignores and immediately removes all counters and/or the affects of Poison.');
/*Immune: Slow							--Index 680*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Immune: Slow', 'A model with Immune: Slow ignores and immediately removes all counters and/or the affects of Slow.');
/*Immune: Status Effects				--Index 681*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Immune: Status Effects', 'A model that is Immune: Status Effects can never suffer the negative effects of status effects.  If a model that is suffering a status effect gains Immune: Status Effects remove all status effect tokens immediately.');
/*Impale								--Index 682*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Impale', 'When a model with Impale destroys a Hero, spawn two Nether Imps adjacent to the Hero before removing it.');
/*Impale								--Index 683*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Impale', 'When a model with Impale achieves a critical success, spawn a Nether Imp within three squares of it.');
/*Improved Critical						--Index 684*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Improved Critical', 'This model''s Critical hits inflict an additional wound.');
/*Improved Critical						--Index 685*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Improved Critical', 'This model''s critical successes inflict an additional wound.');
/*Infested								--Index 686*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Infested', 'When a Spawning Point model with Infested is destroyed, spawn up to four Dirty Rats from it before removing it.  These Dirty Rats form a Rat King Elite Gang.');
/*Infested								--Index 687*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Infested', 'When a model with Infested is destroyed, spawn up to 4 Skull Points worth of monsters with the Vermin ability within 3 squares of it before removing it.');
/*Insight								--Index 688*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Insight', 'When a model with Insight is targeted by an offensive action, it may force the attacker to reroll one die of its choice from the offense roll, before making a defense roll.<br>(Arcade: A monster targeting a model with Insight reduces its STR by 1.)');
/*Insight								--Index 689*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Insight', 'When a model with Insight is targeted by an offensive action, it may force the attacker to reroll one die of its choice from the offense roll, before making a defense roll.');
/*Insight								--Index 690*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Insight', 'When a model with Insight is targeted by an offensive action, it may force the attacker to reroll one die of its choice from the offense roll, before making a defense roll. (Arcade: A monster targeting a model with Insight reduces its STR by 1.)');
/*Insignificant							--Index 691*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Insignificant', 'If a Hero is on the same dungeon tile as a monster with Insignificant, the monster may be activated in addition to any other monsters that are activated during the Consul Turn.  A model may not draw a loot card for destroying a model with Insginificant.');
/*Insignificant							--Index 692*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Insignificant', 'Models with Insignificant are not counted when determining loot.');
/*Insignificant							--Index 693*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Insignificant', 'Models with Insignificant are not counted when determining loot.');
/*Invader								--Index 694*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Invader', 'When a model with Invader moves adjacent to a Hero immediately remove the model from play and place it on the Hero''s card.  The Invader model may not voluntarily leave the Hero.  The Hero suffers the effects caused by the Invader as long as the Invader model remains on their card.<br><br>Only the affected Hero may target or destroy Invader models on their card.  The Invader is always considered in range.  The Invader cannot be affected by area effects.');
/*Invader								--Index 695*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Invader', 'When a model uses an action with Invader, remove the model from play and place it on the Hero''s card.  The Invader model may not voluntarily leave the Hero.  The Hero suffers the effects caused by the Invader action as long as the Invader model remains on their card.<br><br>Only the affected Hero may target or destroy Invader models on their card.  The Invader is always considered in range.  The Invader cannot be affected by area effects.');

/*Jealous Monkey						--Index 696*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Jealous Monkey', 'A Hero with Jealous Monkey may not equip any new equipment cards (those already on the Hero may stay).');
/*Journey, The							--Index 697*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Journey, The', 'Dungeon bosses whose entire base is on the same tile as one or more models with The Journey gain one of the following, depending on which tile this model is on:<br>First Tile: Massive Damage<br>Second Tile: +2R DEX<br>Third Tile: +2R WILL.');

/*Keep It On Ice						--Index 698*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Keep It On Ice', 'Whenever a model with Keep It On Ice would suffer a wound, instead place the wound on the backpack. At the end of the turn, roll 1R for each wound on the backpack. For each die that rolled no stars, place one of the wounds from the backpack onto the Hero with Keep It On Ice that suffered the wound then discard the rest of the wounds.');
/*Keep The Sake Flowing					--Index 699*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Keep The Sake Flowing', 'A model with Keep The Sake Flowing may drink two potions per turn (both Hero and Consul), so long as the potions are different.  During the party''s power-up, if the model has no potion tokens, it suffers one wound.');
/*Killamari								--Index 700*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Killamari', 'When a model with Killamari is destroyed by another model, place a tentacles token on the model that destroyed it, for the remainder of the game (you can use a crystal token to represent the tentacles token).  When calculating wrath, count this token as one wrath.');
/*Killamari								--Index 701*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Killamari', 'When a model with Killamari is destroyed by another model, place a tentacles token on the model that destroyed it for the remainder of the game. (You may use a crystal token to represent the tentacles token).');
/*Killamari								--Index 702*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Killamari', 'When a model with Killamari is destroyed by another model, place a tentacles token on the model that destroyed it for the remainder of the game. (You may use a crystal token to represent the tentacles token).');
/*Kindling								--Index 703*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Kindling', 'A model adjacent to a model with Kindling cannot remove FIRE status effect tokens at the end of its activation.');
/*Kitty Claws							--Index 704*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Kitty Claws', 'Immediately make one Melee Attack against any enemy model that moves into a square adjacent to a model with Kitty Claws.');
/*Knockdown								--Index 705*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Knockdown', 'A model or effect with Knockdown places a Knockdown counter on any model it damages. A model suffering Knockdown may not move or perform any other action until it spends one action point to remove the counter and stand up.'); 
/*Knockdown								--Index 706*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Knockdown', 'A model suffering Knockdown may not move or perform any other action until it spends one action point or all of its movement points to remove the Knockdown token.');
/*Knockdown								--Index 707*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Knockdown', 'A monster suffering Knockdown may not perform commands until the next Move command. Instead of moving it must remove the Knockdown token.');
/*Knockdown								--Index 708*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Knockdown', 'A model suffering Knockdown may not move or perform any other action until it spends one action point or all of its movement points to remove the Knockdown token.');
/*Knockdown								--Index 709*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Knockdown', 'A model suffering Knockdown may not move or perform any other action until it spends one action point or all of its movement points to remove the Knockdown token.(Arcade: A monster suffering Knockdown may not perform commands until the next Move command. Instead of moving it must remove the Knockdown token.)');
/*Knocked To My Senses					--Index 710*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Knocked To My Senses', 'When a model with Knocked To My Senses suffers a wound, it rolls 1R. If it rolls no stars, it Shapeshifts to its original form.');
/*Know Fate								--Index 711*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Know Fate', 'One use only. When this model would be destroyed, discard Death''s Notebook to immediately Heal 3 and remove all status effects.');

/*Lantern Curse							--Index 712*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Lantern Curse', 'Spawn two Chochin-Obake in any open doorway.');
/*Leadership							--Index 713*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Leadership', 'If another Hero activates after this Hero, during the same turn, that Hero gains +1 action during the activation. This bonus action may only be used on support actions.');
/*Lifedrain								--Index 714*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Lifedrain', 'When a model with Lifedrain destroys a Hero, place a crystal token on the model with Lifedrain. When a model with Lifedrain would be destroyed, it may instead discard a crystal token to Heal 2.');
/*Liver of Steel						--Index 715*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Liver of Steel', 'This Hero may not take potion actions.');
/*Loot Penata							--Index 716*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Loot Pinata', '');  --!! Loot Stash card !!
/*Lost Hero								--Index 717*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Lost Hero', 'When this Hero is destroyed, its player must choose a new Hero. The new Hero retains all equipment except this Treasure. A Princess Coin is not used to bring the Hero into play.');
/*Luck									--Index 718*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Luck', 'When a model with Luck draws treasure cards, it may draw one addtional card.  Choose one of the cards drawn and shuffle it back into the deck.');
/*Lucky Cat								--Index 719*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Lucky Cat', 'When a model with Lucky Cat rolls dice, it may choose to reroll any dice it wishes (dice may only be rerolled once).');

/*Malice								--Index 720*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Malice', 'During the Consul''s power-up phase, all Heroes with Malice move two spaces towards the closest other Hero and then must take a basic offensive action against the closest other Hero, if able.');
/*Mamma Knows							--Index 721*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Mamma Knows', 'Mother Noctua gains +1G STR while targeting this model with offensive actions.');
/*Mamma's Mad							--Index 722*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Mamma''s Mad', 'After a model with Mamma''s Mad is destroyed, all friendly dungeon bosses in play immediately take the first unique action listed on their card.');
/*Mamma's Mad							--Index 723*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Mamma''s Mad', 'After one or more Yowlings is destroyed by an action, a model with Mamma''s Mad may immediately take the Deeproot Rage action without spending any actions points.');
/*Mark									--Index 724*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Mark', 'Place a crystal token on the target.  Friendly models attacking the target gain +1B to their offense rolls.  Only one friendly Mark token may be in play at one time and it may not be removed until the target is destroyed or Mark is used again.');
/*Mark The Path							--Index 725*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Mark The Path', 'When the dungeon boss spawns, spawn six Waystone Creeps; two in the first tile, two in the second tile, and two in the third tile.  In each tile one Waystone must be spawned within two squares of the SPAWNPOINT and the other must be spawned within two squares of any open doorway.');
/*Massive Damage						--Index 726*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Massive Damage', 'When an offensive action with Massive Damage inflicts a wound, it inflicts two wounds instead.');
/*Massive Damage						--Index 727*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Massive Damage', 'When an offensive action with Massive Damage inflicts a wound it instead inflicts two wounds.');
/*Massive Damage						--Index 728*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Massive Damage', 'When an offensive action with Massive Damage inflicts a wound, it inflicts one additional wound.');
/*Massive Damage						--Index 729*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Massive Damage', 'When an offensive action with Massive Damage inflicts a wound, it inflicts two wounds instead.');
/*Master Gains: Bane					--Index 730*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Master Gains: Bane (X)', 'The model controlling this model gains the keyword "Bane" when they are within X spaces of one another.');
