/*Spirit Call							--Index 993*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Spirit Call', 'When a model with Spirit Call is in play, all Ghost models gain +1B to all rolls.');
/*Spirit Sentry							--Index 994*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Spirit Sentry', 'When a model with Spirit Sentry either deals or suffers a wound, all SUPER monsters in play may immediately make one basic attack action.');
/*Spiteful Whispers						--Index 995*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 	'Spiteful Whispers', 'A model with a Spiteful Cherub on its card suffers -1ST WILL to all WILL rolls.  The Hero must also roll 1G at the end of every Consul turn and apply one of the below status effects, depending on the roll:<br>0ST: Bane<br>1ST: Hex<br>2ST: Ice<br>3ST: Poison<br>4ST: Immobile');
/*Spiteful Whispers						--Index 996*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Spiteful Whispers', 'Heroes suffer -1ST WILL for each model with Spiteful Whispers adjacent to them.');
/*Splinters								--Index 997*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Splinters', 'When a model with Splinters achieves a Critical Success, it suffers one damage.');
/*Splinters								--Index 998*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Splinters', 'When a model with Splinters achieves a critical hit, it suffers one damage.');
/*Spongy								--Index 999*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Spongy', 'When a model with Spongy is targeted by an action, after the action has been resolved, move the model that targeted it one square using the rules for Push.  Resolve Spongy even if the model with Spongy was destroyed.');
/*Spooky Spooky!						--Index 1000*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Spooky Spooky!', 'At the end of this model’s activation, it may cause target adjacent Hero to Push 3.');
/*Spread The Cheer						--Index 1001*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Spread The Cheer', 'The first time per turn a model with Spread The Cheer suffers a wound, it may apply the wound to the closest enemy model instead.');
/*Spread The Love						--Index 1002*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 	'Spread The Love', 'After a monster with Spread The Love performs a Fight command that dealt one or more wounds, roll 1G for each Hero that suffered at least one wound and apply one of the following status effects depending on the roll:<br>HEART POTION: Bane<br>1ST: Hex<br>2ST: Ice<br>3ST: Poison<br>4ST: Immobile');
/*Spread The Love						--Index 1003*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Spread The Love', 'When a model with Spread The Love makes a successful offensive action, it may choose and apply one status effect on the target for each potion rolled.  These status effects are applied after fully resolving the action.');
/*Spread The Love						--Index 1004*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Spread The Love', 'When a model with Spread The Love makes a successful offensive action, it may choose and apply one status effect on the target for each potion rolled.');
/*Squirrely								--Index 1005*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Squirrely', 'When a model with Squirrely makes a defense roll, it may choose one of its dice and reroll it.');
/*Steady								--Index 1006*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Steady', 'A model with Steady may not be Pushed, Pulled, or Compelled by enemy models.');
/*Steady								--Index 1007*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Steady', 'A model with Steady may not be Pushed, Pulled, or Compelled by enemy models.');
/*Steal									--Index 1008*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Steal', 'When a model with Steal inflicts a wound, it may discard one random card from the party''s backpack.');
/*Stealth								--Index 1009*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Stealth', 'Actions targeting a model with Stealth reduce their Range by 3, to a minimum of 1.');
/*Stealth Aura							--Index 1010*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Stealth Aura', 'Monsters with RUBYAFFINITY that are within two squares of a model with Stealth Aura gain Stealth.');
/*Stingy								--Index 1011*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Stingy', 'A model with Stingy may not share its potions with friendly Heroes.');
/*Stocked								--Index 1012*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Stocked', 'A model with Stocked begins the game with its maximum number of potions.');
/*Storm Of Rage And Grief, A			--Index 1013*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Storm Of Rage And Grief, A', 'All Heroes must roll thier STR.  Any Heroes that roll 3 or fewer stars suffer KNOCKDOWN.  Then, if Ugg or Mugg is in play, the remaining Dungeon Boss immediately performs a full activation (this may interrupt the Heroes'' turn).');
/*Strength of Virtue					--Index 1014*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Strength of Virtue', 'When a model with Strength of Virtue would gain a status effect, it may roll 1B.  If any stars are rolled, it does not gain the status effect.');
/*Strike								--Index 1015*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Strike', 'This Pet’s Master gains Pounce on its basic Melee attack if it has one and it began its activation within 2 squares of this Pet.');
/*Structure								--Index 1016*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Structure', 'Models cannot draw line of sight across or move through structures.');
/*Stubborn Goat							--Index 1017 */	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Stubborn Goat', 'A Model with Stubborn Goat may not move during its activation unless the Heroes choose to discard one loot card from the backpack at the start of its activation.'); --!
