/*Vermin								--Index 1055*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Vermin', 'This model may be spawned by the Infested ability.');
/*Vile Stench							--Index 1056*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Vile Stench', 'Enemy models may not end a move adjacent to this model unless they take a WILL check and roll one or more stars. (Arcade: At the end of each Hero turn, discard 1 Wrath from this model).');
/*Virulent								--Index 1057*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Virulent', 'Add +1B to this model''s offense rolls if its target is suffering from Poison.');
/*Volatile								--Index 1058*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Volatile', 'When a model with Volatile is destroyed, before removing the model, resolve the following action: 2AC 0SW, +2R STR, Wave 1')
/*Volatile								--Index 1059*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Volatile', 'When a model with Volatile is destroyed, before removing the model, resolve the following action: 1AC 0SW, Wave 1, +2R STR.')
/*Volatile								--Index 1060*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Volatile', 'When a model with Volatile is destroyed, before removing the model, resolve the following action: 0AC Wave 1, +3ST STR. When Volatile is triggered, the model with Volatile is destroyed.')
/*Volatile								--Index 1061*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Volatile', 'When a model with Volatile is destroyed, before removing the model, resolve the following action: 0Melee, Wave 1, +2R STR.')

/*WAAAAAAAAAAAAAAAAAGGHHH!!!!			--Index 1062*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'WAAAAAAAAAAAAAAAAAGGHHH!!!!', 'Place a Battle Frenzy token on every Orc, Goblin, and Gnoll except the dungeon boss.  When a model would suffer one or more damage, it may discard a Battle Frenzy token to reduce the damage to zero.');
/*Warcry								--Index 1063*/	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Warcry', 'When a model with Warcry succeeds with an offensive action, spawn a number of Goblin Creeps adjacent to the target equal to the number of Potion icons rolled. This may not result in more than four Goblim Creeps being in play.'); 
/*Watch Out!							--Index 1064*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Watch Out!', 'When a Boo Booty spawns on the same tile as this model, the Boo Booty suffers two wounds.');
/*Way Keeper							--Index 1065*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Way Keeper', 'Friendly Waystone Creeps gain +1G ARM while on the same tile as a model with Way Keeper.');
/*Wayfarer								--Index 1066*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Wayfarer', 'A model with Wayfarer is affected by The Journey ability as if it were a dungeon boss.');
/*Webs									--Index 1067*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Webs', 'All squares within two squares of a model with Webs are difficult terrain.');
/*Welcome To The Black Parade			--Index 1068*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Welcome To The Black Parade', 'Spawn two Curse Ravens adjacent to the spawning point icon on the third tile.');
/*Werecursed (X)						--Index 1069*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Werecursed (X)', 'When the Consul reaches a purple space on the Mighty Monster Chart, a model with Werecursed will Shapeshift into the listed model.');
/*Widow's Secret, The					--Index 1070*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Widow''s Secret, The', 'Heroes within Aura 4 suffer -1ST WILL to all WILL rolls.');
/*Wind of Blades						--Index 1071*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Wind of Blades', 'A model with Wind of Blades may spend all of its movement points to make a single Missile Attack basic offensive action.');
/*Wind of Blades						--Index 1072*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Wind of Blades', 'If a model with Wind of Blades didn''t move in the turn before attacking, it (or its gang) gains +1ST STR for the remainder of the turn.');
/*Wisdom								--Index 1073*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Wisdom', 'A model with Wisdom gains +1AC that may only be used to take support actions.');

/*Yip's Wrath							--Index 1074*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Yip''s Wrath', 'During its activation, a model with Yip''s Wrath may make the following offensive action a single time for free:  0AC: 4MI, Knockdown.');
/*										--Index 1076*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('', '', '', '');
/*Yoink!								--Index 1076*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'Yoink!', 'When a monster with Yoink! attacks a Hero and the Hero rolls zero stars for defense, the Hero must discard one equipped loot card at random, if able.');
/*Yoink!								--Index 1077*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Yoink!', 'When a model with Yoink! achieves a critical success, its target must discard one equipped loot card at random, if able.');
/*You're Alone							--Index 1078*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 	'You''re Alone', 'A model with You''re Alone gains +2ST STR when targeting a model that has no other models friendly to it within two squares.');
/*You're Alone							--Index 1079*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'You''re Alone', 'A model with You''re Alone gains +2B to offensive actions that are targeting a model that has no other models friendly to it within two squares.');
/*You've Been Naughty					--Index 1080*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Arcade', 'You''ve Been Naughty', 'After an enemy model rolls a critical success against a model with You''ve Been Naughty, the enemy model Shapeshifts into a Naughtie (regardless of the number of wounds dealt by the critical).  The controller of the model that is shapeshifting selects one Naughtie shapeshift card that is not already being used by a Hero.  If all Naughtie shapeshift cards are in play, this ability has no effect.  Heroes on Kringle''s Nice List may not be shapeshifted in this way.');
/*You've Been Naughty					--Index 1081*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'You''ve Been Naughty', 'After an enemy model rolls a critical success against a model with You''ve Been Naughty, the enemy model Shapeshifts into a Naughtie (regardless of the number of wounds dealt by the critical).  The Consul selects one Naughtie shapeshift card that is not already being used by a Hero.  If all Naughtie shapeshift cards are in play, this ability has no effect.  Heroes on Kringle''s Nice List may not be shapeshifted in this way.');
/*Your Goddess Has Forsaken You			--Index 1082*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Your Goddess Has Forsaken You', 'All enemy Heroes discard all spent Princess Coins from their cards.  All enemy Heroes without Princess Coins to discard suffer one wound.');

/*Impulsive								--Index 1083*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Impulsive', 'When a model with Impulsive activates, roll 1R and apply the following depending on the number of stars rolled:<br>0ST: This model gains Brutal Strike this activation.<br>1ST: This model gains Improved Critical this activation.<br>2ST+: This model gains Brutal Strike and Improved Critical this activation.');
/*Hex									--Index 1084*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Hex', 'A model suffering Hex discards the highest result rolled antime it makes an offense roll. After dice are rolled by any Hero for any reason, this model may discard the die to add it to the roll.');
/*Heart Attack							--Index 1085*/ insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Heart Attack', 'When making an offense roll, a model with Heart Attack counts any hearts rolled as two hearts.');
/*Pile-On								--Index 1086*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Pile-On', 'A model with Pile-on gains +1R STR if its target is suffering Knockdown.');
/*Silverware							--Index 1087*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Silverware', 'All Spikers in play gain +1G STR.');
/*Delicious								--Index 1088*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Delicious', 'When adjacent to this model, The Guth may discard this equipment (ignoring Cursed) as if it were a friendly Goblin Creep to activate Pig Feed.');
/*Brutality Aura						--Index 1089*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Explore', 'Brutality Aura', 'All models, friendly or enemy, that are within two squares of a model with Brutality Aura gain +1ST ARM.');
