/*Ice Fiends				--Index 1150*/	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Ice Fiends', 			'When this model achiees a critial success, summon one Frost Imp adjacent to it if there are fewer than six Frost Imps in play.');
/*Chip Off The Block		--Index 1151*/	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Chip Off The Block', 	'When a model with Chip Off The Block suffers a critical from an enemy''s offensive action, spawn a Frost Imp within three squares of it (up to a maximum of six Frost Imps in play).');
/*Serving Size				--Index 1152*/	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('2.0', 'Default', 'Serving Size', 		'When equipped, place 6 tokens on this Treasure card, to represent 6 servings.  When the last token is discarded, discard this Treasure.');
