/*Lance								--Index 1154*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('1.0', 'Default', 'Lance', 'A Lance effect draws a straight Line in any direction, directly away from the user''s base along a distance of X. Every model along this Line is hit. Lance effects may not be used along diagonals.');
/*Massive Damage					--Index 1155*/ 	insert into Keywords (KeywordVersion, PlayMode, Name, KeywordDescription) VALUES ('1.0', 'Default', 'Massive Damage', 'When an offensive action with Massive Damage inflicts a wound it instead inflicts two wounds.');






