--Miserable Toad --CardIndex 182	--CharacterIndex 97	--ExploreCharacterIndex 97
insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor) VALUES (182, 
