--Royal Warden --CardIndex 198	--CharacterIndex 113	--ExploreCharacterIndex 113
insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor) VALUES (198, 
