--Giri --CardIndex 229	--CharacterIndex 144	--ExploreCharacterIndex 144
insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor) VALUES (229, 'Giri',
