--Claw Trainer --CardIndex 274 --CharacterIndex 189 --ExploreCharacterIndex 189
insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor) VALUES (274, 
