--Kinoshroom --CardIndex 287 --CharacterIndex 202 --ExploreCharacterIndex 202
insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor) VALUES (287, 
