--Knucklehead --CardIndex 300 --CharacterIndex 215 --ExploreCharacterIndex 215
insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor) VALUES (300, 
