--Burning Gel --CardIndex 303 --CharacterIndex 218  --ExploreCharacterIndex 218
insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor) VALUES (303, 
