--Mook --CardIndex 308 --CharacterIndex 223 --ExploreCharacterIndex 223
insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor) VALUES (308, 
