--Trent --CardIndex 371	--CharacterIndex 286	--ArcadeCharacterIndex 34
insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor) VALUES (371, 'Trent',
