--Goro --CardIndex 374	--CharacterIndex 289	--ArcadeCharacterIndex 37
insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor) VALUES (374, 'Goro',
