--Rex	--CardIndex 1320	--CharacterIndex 930	--ArcadeCharacterIndex 162
insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor) VALUES (1320, 'Rex',
