--Spicey Turnips	--CardIndex 1423	--CharacterIndex 1033	--ArcadeCharacterIndex 265
insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor) VALUES (1423, 'Spicey Turnips',
'https://htkb.info/ND/SDE/2.0/Cards/Arcade/Warbands/Fire_Flow_Hollow/Card_Arcade_Warband_Fire_Flow_Hollow_Spicey_Turnips_2.0.png', 
'https://htkb.info/ND/SDE/2.0/Cards/Arcade/Warbands/Fire_Flow_Hollow/Card_Arcade_Warband_Fire_Flow_Hollow_Spicey_Turnips_2.0_back.png', 
'http://htkb.online/SDWiki/SDE/2.0/Arcade/Cards/Warbands/Fire_Flow_Hollow/Spicey_Turnips.xhtml', 
'Warband', '2.0', '2.0 Core Set', 'Arcade', 
'Spicy Turnips are Turnipheads who have given up on healing wounded plants. In the harsh conditions of the Dragonback Peaks, a Turniphead cannot properly heal every burn, every lost leaf, every torn root. This frustration builds in fiery rage, and a Spice Turnip is born. Unable to heal the wounded, Spicy Turnips instead seek to stoke the flames.');
