--Volcanic Growth	--CardIndex 1425	--CharacterIndex 1035	--ArcadeCharacterIndex 267
insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor) VALUES (1425, 'Volcanic Growth',
'https://htkb.info/ND/SDE/2.0/Cards/Arcade/Warbands/Fire_Flow_Hollow/Card_Arcade_Warband_Fire_Flow_Hollow_Volcanic_Growth_2.0.png', 
'https://htkb.info/ND/SDE/2.0/Cards/Arcade/Warbands/Fire_Flow_Hollow/Card_Arcade_Warband_Fire_Flow_Hollow_Volcanic_Growth_2.0_back.png', 
'http://htkb.online/SDWiki/SDE/2.0/Arcade/Cards/Warbands/Fire_Flow_Hollow/Volcanic_Growth.xhtml', 
'Warband', '2.0', '2.0 Core Set', 'Arcade', 
'As a Magma Seed grows, it blossoms into the mighty Volcanic Sprout. By the time these sprouts reach maturity they have spent centuries encased in lava and the experience has left them hardened and formidable. Relishing in the open air, they grow at an astounding rate, burning anything in their path, except perhaps the Broiled Mooks who find the conflagration more amusing as it grows.');
