--Scrap Tower
--Scrap Tower --CardIndex 1459 --CharacterIndex 1069 --ArcadeCharacterIndex 301
insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor) VALUES (1459, 'Scrap Tower',
'https://htkb.info/ND/SDE/2.0/Cards/Arcade/Warbands/Scrap_Tower/Card_Arcade_Warband_Scrap_Tower_2.0.png', 
'https://htkb.info/ND/SDE/2.0/Cards/Arcade/Warbands/Scrap_Tower/Card_Arcade_Warband_Scrap_Tower_2.0_back.png', 
