--Spinner Spindle	--CardIndex 1486	--CharacterIndex 1096	--ArcadeCharacterIndex 328
insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor) VALUES (1486, 'Spinner Spindle',
'https://htkb.info/ND/SDE/2.0/Cards/Arcade/Warbands/Spider_Nest/Card_Arcade_Warband_Spider_Nest_Spinner_Spindle_2.0.png', 
'https://htkb.info/ND/SDE/2.0/Cards/Arcade/Warbands/Spider_Nest/Card_Arcade_Warband_Spider_Nest_Spinner_Spindle_2.0_back.png', 
'http://htkb.online/SDWiki/SDE/2.0/Arcade/Cards/Warbands/Spider_Nest/Spinner_Spindle.xhtml', 
'Warband', '2.0', '2.0 Core Set', 'Arcade', 
'Shadow spinners lurk within dark spaces of the the Nether Rifts, weaving webs of pure shadow to conceal their presence and ensnare their prey. Many shadow spinners have taken up residence within the Midnight Tower. Their webs of pure darkness blend perfectly with the natural gloom of the tower, and they are an ever-present danger to anyone foolish enough to enter.');  
