insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor) VALUES (1915, 
'Stampeding Booty',
'https://htkb.info/ND/SDE/2.0/Cards/Treasure/Booty/Card_Treasure_Stampeding_Booty_2.0.png', 
'https://htkb.info/ND/SDE/2.0/Cards/Treasure/Card_Treasure_Back_2.0.png',
