'Utility', '2.0 DI', '2.0 Devil Island Set', 'Default', '');
insert into Utilities (CardIndex, UtilityDescription) VALUES (2015, 'DICE CONVERSION</br><br><br>If you do not have Super Dungeon dice, you can instead use three colors of standard six-sided dice. Below is a conversion chart for using standard dice until you get a set of Super Dungeon dice!</br><br><br></br>');

--Hero Turn Summary	--CardIndex 2016 --UtilityIndex 33
insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor)
VALUES (2016, 'Hero Turn Summary',
'https://htkb.info/ND/SDE/2.0/Cards/Utility/Card_Utility_Hero_Turn_Summary_2.0.png', 
'https://htkb.info/ND/SDE/2.0/Cards/Utility/Card_Utility_Hero_Turn_Summary_2.0.png', 
