insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor)
VALUES (2181, 'Vrroooom!',
'https://htkb.info/ND/SDE/2.0/Cards/Arcade/Challenges/Boss_Challenges/Professor_Cackle_Clink/Card_Boss_Challenge_Vrroooom_2.0.png', 
'https://htkb.info/ND/SDE/2.0/Cards/Arcade/Challenges/Backs/Card_Boss_Challenge_Yellow_Back_2.0.png', 
