--Bounty	--CardIndex 2210 --UtilityIndex 121 --DifficultyIndex 0
insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor)
VALUES (2210, 'Bounty',
'https://htkb.info/ND/SDE/2.0/Cards/Difficulty/Card_DIfficulty_Easy_Mode_Bounty_2.0.png', 
'https://htkb.info/ND/SDE/2.0/Cards/Difficulty/Card_DIfficulty_Easy_Mode_Back_2.0.png', 
'http://htkb.online/SDWiki/SDE/2.0/Cards/Difficulty_Cards/Easy_Cards/Bounty.xhtml', 
'Difficulty Card', '2.0', '2.0 Core Set', 'Default', 'You''re saying that if we raid the Midnight Tower, seat of the Dark Consul''s power in this world, we get to keep all the loot we find there AND we get free cookies for life when we come back?<br><br>We''d better hurry before some other heroes beat us to it!');
insert into Utilities (CardIndex, UtilityDescription) VALUES (2210, 'During the Heroes'' power-up, they draw one treasure for each Elite destroyed that had three or more hearts, instead of one loot.');
insert into DifficultyAssignments (UtilityIndex, DifficultyIndex) VALUES (121,0);

--Coin on a String	--CardIndex 2211 --UtilityIndex 122 --DifficultyIndex 1
insert into Cards (ComponentIndex, Name, PictureFront, PictureBack, Link, CardType, ProductSet, ProductModule, PlayMode, Flavor)
VALUES (2211, 'Coin on a String',
'https://htkb.info/ND/SDE/2.0/Cards/Difficulty/Card_DIfficulty_Easy_Mode_Coin_on_a_String_2.0.png', 
'https://htkb.info/ND/SDE/2.0/Cards/Difficulty/Card_DIfficulty_Easy_Mode_Back_2.0.png', 
'http://htkb.online/SDWiki/SDE/2.0/Cards/Difficulty_Cards/Easy_Cards/Coin_on_a_String.xhtml', 
'Difficulty Card', '2.0', '2.0 Core Set', 'Default', 'So, we have sacred Princess Coins, relics of the Goddess herself and... you put one on a string to get more uses out of it?<br><br>I love it!');
insert into Utilities (CardIndex, UtilityDescription) VALUES (2211, 'Once per turn, during power-up, the party may discard four loot cards from the backpack to gain a Princess Coin.');
insert into DifficultyAssignments (UtilityIndex, DifficultyIndex) VALUES (122,0);

